<?php $title='Fehlerprotokoll'; ?>
<div class="page-header"><div><p class="eyebrow">Administration · Technik</p><h1>Fehlerprotokoll</h1><p>Technische Fehler mit internen Details; normale Benutzer sehen keine Stacktraces.</p></div></div>
<div class="panel"><form method="get" action="<?= e(url('admin/errors')) ?>" class="filterbar"><select name="status"><option value="">Alle Status</option><option value="open" <?= $filters['status']==='open'?'selected':'' ?>>Offen</option><option value="reviewed" <?= $filters['status']==='reviewed'?'selected':'' ?>>Geprüft</option><option value="done" <?= $filters['status']==='done'?'selected':'' ?>>Erledigt</option></select><input name="module" value="<?= e($filters['module']) ?>" placeholder="Modul"><button class="button secondary" type="submit">Filtern</button></form>
<div class="timeline-list"><?php foreach($errors as $e):?><details class="timeline-item"><summary><span class="badge <?= $e['status']==='done'?'active':($e['status']==='reviewed'?'neutral':'warning') ?>"><?= e($e['status']) ?></span> <strong><?= e(mb_strimwidth($e['message'],0,150,'…')) ?></strong> · <?= e(format_datetime($e['occurred_at'])) ?></summary><p>Modul: <?= e($e['module']??'–') ?> · Benutzer: <?= e($e['user_name']??'–') ?></p><pre style="white-space:pre-wrap;max-height:420px;overflow:auto"><?= e($e['technical_details']??'') ?></pre><?php if(can('system.errors.manage')):?><form method="post" action="<?= e(url('admin/errors/'.$e['id'].'/status')) ?>" class="inline-actions"><?= csrf_field() ?><select name="status"><option value="open">Offen</option><option value="reviewed">Geprüft</option><option value="done">Erledigt</option></select><button class="button secondary compact" type="submit">Status speichern</button></form><?php endif;?></details><?php endforeach;?><?php if($errors===[]):?><div class="empty">Keine Fehler gefunden.</div><?php endif;?></div></div>
